import (
	"encoding/json"
	"os"
	"path/filepath"
	"runtime"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 10

// thresholdsPath 指向仓库根目录下的 config/thresholds.json。
//
// 配置按仓库名给出阈值，例如 {"shanghai": 20}。路径以本源文件为锚点解析，
// 这样无论进程从哪个工作目录启动都能找到 config/。
var thresholdsPath = func() string {
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		return filepath.Join("config", "thresholds.json")
	}
	return filepath.Join(filepath.Dir(file), "..", "config", "thresholds.json")
}()

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 在 config/thresholds.json 里配置过的仓库用它自己的阈值，其余（含配置缺失
// 或不可用时）回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	if threshold, ok := loadThresholds()[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取并解析阈值配置。
//
// 文件不存在、读不出来、内容不是 JSON 对象（或含非整数阈值）时返回 nil，
// 调用方据此回退到默认值。
func loadThresholds() map[string]int {
	data, err := os.ReadFile(thresholdsPath)
	if err != nil {
		return nil
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

