package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// writeThresholds 把内容写进临时文件并返回路径。
func writeThresholds(t *testing.T, contents string) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "thresholds.json")
	if err := os.WriteFile(path, []byte(contents), 0o600); err != nil {
		t.Fatalf("写测试配置失败: %v", err)
	}
	return path
}

// useThresholds 临时把读取路径指向 path，测试结束恢复。
func useThresholds(t *testing.T, path string) {
	t.Helper()
	original := thresholdsPath
	thresholdsPath = path
	t.Cleanup(func() { thresholdsPath = original })
}

func TestDefaultLowStockThresholdIsTen(t *testing.T) {
	if DefaultLowStockThreshold != 10 {
		t.Fatalf("DefaultLowStockThreshold = %d, 期望 10", DefaultLowStockThreshold)
	}
}

func TestLowStockThresholdUsesConfiguredValue(t *testing.T) {
	useThresholds(t, writeThresholds(t, `{"shanghai": 20}`))

	if got := LowStockThreshold("shanghai"); got != 20 {
		t.Fatalf("LowStockThreshold(shanghai) = %d, 期望 20", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("LowStockThreshold(chengdu) = %d, 期望默认值 %d", got, DefaultLowStockThreshold)
	}
}

func TestIsLowStockUsesConfiguredThreshold(t *testing.T) {
	useThresholds(t, writeThresholds(t, `{"shanghai": 20}`))

	if !IsLowStock("shanghai", 19) {
		t.Fatal("低于配置阈值应当算低库存")
	}
	if IsLowStock("shanghai", 20) {
		t.Fatal("等于配置阈值不算低库存（严格小于）")
	}
}

func TestThresholdsFallbackToDefault(t *testing.T) {
	cases := []struct {
		name  string
		setup func(t *testing.T) string
	}{
		{"文件不存在", func(t *testing.T) string {
			return filepath.Join(t.TempDir(), "missing.json")
		}},
		{"读不出来", func(t *testing.T) string {
			// 路径指向目录，ReadFile 会失败。
			return t.TempDir()
		}},
		{"不是合法 JSON", func(t *testing.T) string {
			return writeThresholds(t, `{not json`)
		}},
		{"不是 JSON 对象", func(t *testing.T) string {
			return writeThresholds(t, `[1, 2, 3]`)
		}},
		{"null", func(t *testing.T) string {
			return writeThresholds(t, `null`)
		}},
		{"阈值不是整数", func(t *testing.T) string {
			return writeThresholds(t, `{"shanghai": "20"}`)
		}},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			useThresholds(t, tc.setup(t))

			if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
				t.Fatalf("LowStockThreshold(shanghai) = %d, 期望默认值 %d", got, DefaultLowStockThreshold)
			}
		})
	}
}

// TestLowStockThresholdReadsRepoConfig 确认默认路径确实落在仓库的 config/ 上，
// 且读到的每个仓库都与配置一致。
func TestLowStockThresholdReadsRepoConfig(t *testing.T) {
	data, err := os.ReadFile(thresholdsPath)
	if err != nil {
		t.Fatalf("读取仓库配置 %s 失败: %v", thresholdsPath, err)
	}

	var configured map[string]int
	if err := json.Unmarshal(data, &configured); err != nil {
		t.Fatalf("解析仓库配置 %s 失败: %v", thresholdsPath, err)
	}
	if len(configured) == 0 {
		t.Fatalf("仓库配置 %s 没有任何条目", thresholdsPath)
	}
	for warehouse, threshold := range configured {
		if got := LowStockThreshold(warehouse); got != threshold {
			t.Fatalf("LowStockThreshold(%q) = %d, 配置值 %d", warehouse, got, threshold)
		}
	}
}
